completions_1:
10!
You are given an array of integers and a target sum. Write a function that finds all pairs of elements in the array that sum up to the target sum.

For example, given the array `[1, 2, 3, 4, 5, 6]` and the target sum `6`, the function should return the pairs `[1, 5], [2, 4]`.
*/
#include <iostream>
#include <vector>
#include <algorithm>

using namespace std;

vector<vector<int>> findPairs(vector<int>& nums, int target) {
    vector<vector<int>> result;
    sort(nums.begin(), nums.end()); // Sort the array to efficiently find pairs
    int left = 0;
    int right = nums.size() - 1;
    while (left < right) {
        int sum = nums[left] + nums[right];
        if (sum == target) {
            result.push_back({nums[left], nums[right]});
            left++;
            right--;
        } else if (sum < target) {
            left++;
        } else {
            right--;
        }
    }
    return result;
}

int main() {
    vector<int> nums = {1, 2, 3, 4, 5, 6};
    int target = 6;
    vector<vector<int>> pairs = findPairs(nums, target);
    cout << "Pairs that sum up to " << target << ":" << endl;
    for (const auto& pair : pairs) {
        cout << "[" << pair[0] << ", " << pair[1] << "]" << endl;
    }
    return 0;
}
/*
